{"output": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if (0 <= a < h and 0 <= b < w and
                            (a, b) not in seen and grid[a][b] == color):
                        seen.add((a, b))
                        q.append((a, b))
            rs = [x for x, _ in cells]
            cs = [y for _, y in cells]
            comps.append((color, cells, min(rs), max(rs), min(cs), max(cs)))
    return comps


def _is_l(comp):
    _, cells, r0, r1, c0, c1 = comp
    if r0 == r1 or c0 == c1:
        return False
    points = set(cells)
    corners = (
        ((r0, c) for c in range(c0, c1 + 1)),
        ((r, c0) for r in range(r0, r1 + 1)),
        ((r0, c) for c in range(c0, c1 + 1)),
        ((r, c1) for r in range(r0, r1 + 1)),
        ((r1, c) for c in range(c0, c1 + 1)),
        ((r, c0) for r in range(r0, r1 + 1)),
        ((r1, c) for c in range(c0, c1 + 1)),
        ((r, c1) for r in range(r0, r1 + 1)),
    )
    # Each adjacent pair of full rectangle edges must describe the whole object.
    pairs = ((0, 1), (2, 3), (4, 5), (6, 7))
    edges = [set(edge) for edge in corners]
    return any(points == edges[a] | edges[b] for a, b in pairs)


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = [v for row in grid for v in row]
    background = max(set(colors), key=colors.count)
