    candidates = []

    for comp in comps:
        color, cells, a0, a1, b0, b1 = comp
        if color in (background, marker_color, 0) or _l_corner(comp) is not None:
            continue
        # Tiny speckles are not target objects in these examples.
        if len(cells) < 3:
            continue

        if corner == "tl":
            if vertical_len < horizontal_len:
                # Short vertical arm: target is on its outside/left side.
                if b1 < c0:
                    gap = c0 - b1 - 1 + max(r0 - a1 - 1, a0 - r1 - 1, 0)
                    candidates.append((gap, cells))
            else:
                # Horizontal arm (or tie): target is above that arm.
                if a1 < r0:
                    gap = r0 - a1 - 1 + max(c0 - b1 - 1, b0 - c1 - 1, 0)
                    candidates.append((gap, cells))
        elif corner == "br":
            # Target lies outside the vertical arm, to its right. Requiring a
            # three-column extent excludes nearby compact distractor blocks.
            if b0 > c1 and b1 - b0 + 1 >= 3:
                gap = b0 - c1 - 1 + max(r0 - a1 - 1, a0 - r1 - 1, 0)
                candidates.append((gap, cells))

    if candidates:
        _, cells = min(candidates, key=lambda item: item[0])
        for r, c in cells:
            out[r][c] = marker_color
    return out


